  {
    "id": "[4]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Chuyện cảm ơn ấy hả, em đã bảo là không cần thiết rồi cơ mà.”"
  },
  {
    "id": "[5]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Gì thế hả, em trai không muốn chị đến à?”"
