  {
    "id": "[8]",
    "dst": "Thế nhưng……"
  },
  {
    "id": "[9]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Có sao không đấy? Bị bà Caroline mà phát hiện là sẽ bị mắng đúng không?”"
  },
  {
    "id": "[10]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Không sao đâu. Đúng là mẹ có dặn là đừng dính dáng gì đến em, nhưng mẹ cũng bảo là đã nhận ơn huệ thì phải biết đền đáp đàng hoàng mà.”"
  },
  {
    "id": "[11]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“……Cái đó, thực sự là một cái cớ dùng được á?”"
  },
  {
    "id": "[12]",
    "speaker_to_listener": "Michelle→Leon",
    "self_ref": "tôi",
    "addr_ref": "thiếu gia",
    "dst": "“Tiểu thư Claire lúc nào cũng thế này cả.”"
  },
  {
    "id": "[13]",
    "dst": "A, tự nhiên thấy thuyết phục hẳn."
  },
  {
    "id": "[14]",
    "dst": "Nhưng mà, nếu chị Claire thấy không vấn đề gì thì chắc là ổn nhỉ. Chị Claire tới đây chơi thì chắc cũng không gây phiền phức gì cho Milly đâu. ……Chắc là không phiền đâu nhỉ?"
  },
  {
    "id": "[15]",
    "dst": "Ném ánh mắt sang nhìn Milly với chút lo lắng, cô liền khẽ gật đầu. Hừm, không phân biệt nổi là ý chỉ ổn thật, hay là đang bảo \"dù không ổn nhưng cứ vậy đi\" nữa."
  },
  {
    "id": "[16]",
    "dst": "Dù không rõ thế nào, nhưng anh vẫn muốn trò chuyện với chị Claire nhiều hơn. Phen này đành nhờ cậy vào Milly vậy."
  },
  {
    "id": "[17]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Cảm ơn chị vì đã đến gặp em nhé, chị Claire.”"
  },
  {
    "id": "[18]",
    "dst": "Vừa lấy hết quyết tâm đáp lời, gương mặt vừa nãy còn có chút lo lắng của chị Claire liền bừng sáng lên trong chớp mắt."
  },
  {
    "id": "[19]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“May quá. Thế thì em trai ơi, tụi mình nói chuyện gì đi nào. Em muốn biết chuyện gì, chị cũng sẽ dạy cho hết tuốt nhé.”"
  },
  {
    "id": "[20]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Ể, thật á? Vậy thì, chị có thể kể cho em nghe về thực vật ở thế giới này được không?”"
  },
  {
    "id": "[21]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“……Thực vật á? Được thôi…… mà em muốn biết loại thực vật thế nào cơ?”"
  },
  {
    "id": "[22]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Để xem nào. Tỷ như là――”"
  },
  {
    "id": "[23]",
    "dst": "Cứ thế, một viên đá mang tên chị Claire đã được ném vào thế giới tĩnh lặng chỉ có hai người."
  },
  {
    "id": "[24]",
    "dst": "Gợn sóng sinh ra từ đó chẳng mấy chốc sẽ biến thành những con sóng lớn, cuốn theo muôn vàn biến cố…… nhưng anh của lúc bấy giờ hoàn toàn không thể ngờ tới điều đó."
  }
]

